package com.minecolonies.api.loot;

import com.minecolonies.api.colony.jobs.ModJobs;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.minecraft.resources.ResourceLocation;

public final class ModLootTables {
    public static final ResourceLocation FISHING = ModJobs.FISHERMAN_ID;
    public static final ResourceLocation FISHING_FISH = new ResourceLocation(String.valueOf(FISHING) + "/fish");
    public static final ResourceLocation FISHING_JUNK = new ResourceLocation(String.valueOf(FISHING) + "/junk");
    public static final ResourceLocation FISHING_TREASURE = new ResourceLocation(String.valueOf(FISHING) + "/treasure");
    public static final Map<Integer, ResourceLocation> FISHERMAN_BONUS = ModLootTables.createFishermanBonusMap();

    private static Map<Integer, ResourceLocation> createFishermanBonusMap() {
        HashMap<Integer, ResourceLocation> map = new HashMap<Integer, ResourceLocation>();
        for (int level = 1; level <= 5; ++level) {
            map.put(level, new ResourceLocation(String.valueOf(FISHING) + "/bonus" + level));
        }
        return Collections.unmodifiableMap(map);
    }
}

